#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++){scanf("%d",&p[i]);p[i]--;}
    vector<pair<int,int>> ops;
    auto apply=[&](int x,int y){
        vector<int> q(n);
        for(int i=0;i<y;i++) q[i]=p[n-y+i];
        for(int i=0;i<n-x-y;i++) q[y+i]=p[x+i];
        for(int i=0;i<x;i++) q[n-x+i]=p[i];
        p=q; ops.push_back({x,y});
    };
    if(n<=2){
        printf("%d\n",(int)ops.size());
        for(auto&[a,b]:ops) printf("%d %d\n",a,b);
        return 0;
    }
    // Place elements 0..n-1 at positions 0..n-1
    for(int t=0;t<n;t++){
        int pos=-1;
        for(int i=t;i<n;i++) if(p[i]==t){pos=i;break;}
        if(pos==t) continue;
        int rem=n-t; // working with positions t..n-1
        // Move p[pos] to position t
        // Step1: bring to end (position n-1)
        if(pos!=n-1){
            int y=n-pos; // y elements from pos..n-1
            int x=max(1,pos-t); // at least 1, elements from t..pos-1 go to end
            if(x==0) x=1;
            if(x+y>=n){y=n-1-x; if(y<=0||x<=0||x+y>=n){apply(1,1);for(int i=t;i<n;i++)if(p[i]==t){pos=i;break;}if(pos==t)continue;y=n-pos;x=max(1,pos-t);}}
            if(pos!=n-1&&x>0&&y>0&&x+y<n) apply(x,y);
            for(int i=t;i<n;i++) if(p[i]==t){pos=i;break;}
        }
        if(pos==t) continue;
        if(pos==n-1&&t+2<=n-1){int x=1;int y=n-1-t;if(x+y<n)apply(x,y);}
        else if(pos!=t&&pos!=n-1){int need=pos-t;if(need>=1&&n-1-need>=1&&need+(n-1-need)<n)apply(need,n-1-need);}
    }
    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
